export const trace = new Trace({
  events: trackingPlan,
  destinations: {
    product: createMockAdapter().adapter,
    backend: createMockAdapter({ name: "backend" }).adapter,
  },
});

export const first = trace.track("Event 000");
export const middle = trace.track("Event 250", { index: 250, label: "a" });

export const last = trace.track(
  "Event 499",
  { index: 499, answer: "no" },
  { to: ["backend"] },
);

expectTypeOf(trace.track<"Event 000">).parameters.toEqualTypeOf<
  [
    name: "Event 000",
    properties?: undefined,
    options?: TrackOptions<"product" | "backend">,
  ]
>();
expectTypeOf(trace.track<"Event 250">).parameters.toEqualTypeOf<
  [
    name: "Event 250",
    properties: { index: 250; label: string },
    options?: TrackOptions<"product" | "backend">,
  ]
>();
expectTypeOf(trace.track<"Event 499">).parameters.toEqualTypeOf<
  [
    name: "Event 499",
    properties: { index: 499; answer: "yes" | "no" },
    options?: TrackOptions<"product" | "backend">,
  ]
>();
expectTypeOf(last).toEqualTypeOf<Receipt<"product" | "backend">>();

// @ts-expect-error The plan has 500 events, and "Event 500" is not one of them.
trace.track("Event 500");

// @ts-expect-error "maybe" is not an answer this event's schema declares.
trace.track("Event 499", { index: 499, answer: "maybe" });

// @ts-expect-error A label is a string.
trace.track("Event 250", { index: 250, label: 3 });

// @ts-expect-error This event requires its properties, however large the plan.
trace.track("Event 250");

// @ts-expect-error This event takes no properties.
trace.track("Event 000", { index: 0 });
